## Code Example
```c
// compute.h
int compute(int input, char* out, int outLen);
```
```c
#include "compute.h"
#include <stdio.h>
#include <string.h>
int compute(int input, char* out, int outLen) {
  char tmp[64];
  int v = input * 2;
  int n = snprintf(tmp, sizeof(tmp), "value=%d", v);
  if (n + 1 > outLen) return -1;
  memcpy(out, tmp, n + 1);
  return n;
}
```
```go
package cgoa

/*
#include "compute.h"
#include <stdlib.h>
*/
import "C"
import (
  "errors"
  "unsafe"
)

func Compute(input int) (string, error) {
  buf := make([]byte, 256)
  n := C.compute(C.int(input), (*C.char)(unsafe.Pointer(&buf[0])), C.int(len(buf)))
  if int(n) < 0 {
    return "", errors.New("overflow")
  }
  s := C.GoStringN((*C.char)(unsafe.Pointer(&buf[0])), C.int(n))
  return s, nil
}
```

